<section class="card"><div class="section-heading"><div><h2>Danh mục hạ tầng</h2><p class="muted">Máy chủ, máy trạm và phân vùng mạng OpenStack.</p></div><a href="#asset-form" class="button">＋ Thêm tài sản</a></div><form method="get" class="filter-form"><?php select_field('network','Lọc theo mạng',[''=>'Tất cả mạng']+array_combine(['Net_LAN (Servers)','Net_DMZ','Net_LAN (IT)','Net_LAN (HR)','Net_LAN (Kế toán)'],['Net_LAN (Servers)','Net_DMZ','Net_LAN (IT)','Net_LAN (HR)','Net_LAN (Kế toán)']),$network) ?><button id="filter-assets" class="button subtle">Lọc</button></form><div class="table-wrap"><table><thead><tr><th>Máy / Vai trò</th><th>Mạng</th><th>Fixed IP</th><th>Floating IP</th><th>Hệ điều hành</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($list as $a): ?><tr><td><strong><?= e($a['ten_may']) ?></strong><small class="cell-subtitle"><?= e($a['vai_tro']) ?></small></td><td><?= e($a['mang']) ?></td><td class="mono"><?= e($a['fixed_ip']) ?></td><td class="mono"><?= e($a['floating_ip']??'—') ?></td><td><?= e($a['he_dieu_hanh']) ?></td><td><?php badge($a['tinh_trang']) ?></td><td><div class="actions"><a class="button subtle" href="/assets?edit=<?= e($a['id']) ?>#asset-form">Sửa</a><form method="post" class="confirm-delete"><?php csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($a['id']) ?>"><button id="delete-asset-<?= e($a['id']) ?>" class="button danger">Xóa</button></form></div></td></tr><?php endforeach ?><?php if(!$list): ?><tr><td colspan="7" class="empty">Không có tài sản phù hợp.</td></tr><?php endif ?></tbody></table></div></section><section class="card narrow" id="asset-form"><h2><?= $edit?'Sửa tài sản':'Thêm tài sản' ?></h2><form method="post" class="form-stack"><?php csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php endif ?><div class="form-grid"><?php field('ten_may','Tên máy',$edit['ten_may']??'','text',100); field('vai_tro','Vai trò',$edit['vai_tro']??'','text',190); select_field('mang','Mạng',array_combine(['Net_LAN (Servers)','Net_DMZ','Net_LAN (IT)','Net_LAN (HR)','Net_LAN (Kế toán)'],['Net_LAN (Servers)','Net_DMZ','Net_LAN (IT)','Net_LAN (HR)','Net_LAN (Kế toán)']),$edit['mang']??''); field('fixed_ip','Fixed IP',$edit['fixed_ip']??'','text',45); field('floating_ip','Floating IP',$edit['floating_ip']??'','text',45,false); field('he_dieu_hanh','Hệ điều hành',$edit['he_dieu_hanh']??'','text',100); select_field('tinh_trang','Trạng thái',['active'=>'Hoạt động','maintenance'=>'Bảo trì','inactive'=>'Ngừng hoạt động'],$edit['tinh_trang']??'active'); ?></div><button id="save-asset" class="button">Lưu tài sản</button><?php if($edit): ?><a href="/assets">Hủy chỉnh sửa</a><?php endif ?></form></section>
